"""The Screensavers page's sentences in the edition's languages. A first draft made with AI assistance, pending native speakers.

T maps an English msgid (or "context|msgid") to its translations in the order of LANGS. A plural entry maps
(singular, plural) to one list of forms per language (Polish three, Japanese, Korean and Chinese one)."""
LANGS = ['pl', 'pt_BR', 'fr', 'de', 'es', 'ja', 'ko', 'zh_CN', 'zh_TW']
PLURAL_FORMS = {
    'pl': 'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);',
    'pt_BR': 'nplurals=2; plural=(n > 1);', 'fr': 'nplurals=2; plural=(n > 1);', 'de': 'nplurals=2; plural=(n != 1);',
    'es': 'nplurals=2; plural=(n != 1);', 'ja': 'nplurals=1; plural=0;', 'ko': 'nplurals=1; plural=0;',
    'zh_CN': 'nplurals=1; plural=0;', 'zh_TW': 'nplurals=1; plural=0;', 'en': 'nplurals=2; plural=(n != 1);'}
